/* @autogenerated */
import { BulkEditField } from 'app/shared/toolkit/bulk-edit/bulk-edit.model';
import { BaseBulkEditAction } from 'app/shared/toolkit/action/base-bulk-edit-action';
import { BulkEditDialogData } from 'app/shared/toolkit/bulk-edit/bulk-edit-dialog.component';
import { Theme } from 'app/features/template/theme/model/theme.model';
import { ThemeRepository } from 'app/features/template/theme/repository/theme-repository.service';
import { Component, inject } from '@angular/core';

/** Edición masiva de theme: los campos que se pueden cambiar en bloque. */
@Component({ selector: 'theme-view-bulk-edit-action', standalone: false, template: '' })
export class ThemeViewBulkEditActionComponent extends BaseBulkEditAction<Theme> {
  readonly name = 'bulkEdit';
  protected readonly scope = 'template/theme';
  protected readonly repository = inject(ThemeRepository);

  protected override keyOf(item: Theme): string {
    return String(item.uid);
  }

  /** Los campos que se pueden editar en bloque y el tipo de cada uno. */
  protected bulkFields(): readonly BulkEditField<Theme>[] {
    return [
      { name: 'tenant', label: this.text('fieldTenant'), type: 'relation', optional: true },
      { name: 'name', label: this.text('fieldName'), type: 'text' },
      { name: 'isDefault', label: this.text('fieldIsDefault'), type: 'boolean', optional: true },
      { name: 'enabled', label: this.text('fieldEnabled'), type: 'boolean', optional: true },
    ];
  }

  protected override toDialogData(count: number): BulkEditDialogData<Theme> {
    return {
      title: this.text('dialogTitle'),
      count,
      singular: this.text('selectedSingular'),
      plural: this.text('selectedPlural'),
      confirm: this.text('confirm'),
      cancel: this.text('cancel'),
      fields: this.bulkFields(),
    };
  }
}
